// n-th point, always keeping the last).
func (q *Queries) TripPoints(ctx context.Context, arg TripPointsParams) ([]TripPointsRow, error) {
	rows, err := q.db.Query(ctx, tripPoints, arg.MaxPoints, arg.TripID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TripPointsRow{}
	for rows.Next() {
		var i TripPointsRow
		if err := rows.Scan(
			&i.RecordedAt,
			&i.Lat,
			&i.Lng,
			&i.AccuracyM,
			&i.SpeedMps,
			&i.Source,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertSourcedLastLocation = `-- name: UpsertSourcedLastLocation :exec
INSERT INTO equipment_last_locations (equipment_id, location, recorded_at, source, accuracy_m, booking_id)
VALUES ($1, ST_SetSRID(ST_MakePoint($2::float8, $3::float8), 4326)::geography, $4, $5,
        $6, $7)
ON CONFLICT (equipment_id) DO UPDATE
SET location = EXCLUDED.location, recorded_at = EXCLUDED.recorded_at, source = EXCLUDED.source,
    accuracy_m = EXCLUDED.accuracy_m, booking_id = EXCLUDED.booking_id, updated_at = now()
WHERE equipment_last_locations.recorded_at < EXCLUDED.recorded_at
`

type UpsertSourcedLastLocationParams struct {
	EquipmentID uuid.UUID     `json:"equipment_id"`
	Lng         float64       `json:"lng"`
	Lat         float64       `json:"lat"`
	RecordedAt  time.Time     `json:"recorded_at"`
	Source      string        `json:"source"`
	AccuracyM   *float32      `json:"accuracy_m"`
	BookingID   uuid.NullUUID `json:"booking_id"`
}

func (q *Queries) UpsertSourcedLastLocation(ctx context.Context, arg UpsertSourcedLastLocationParams) error {
	_, err := q.db.Exec(ctx, upsertSourcedLastLocation,
		arg.EquipmentID,
		arg.Lng,
		arg.Lat,
		arg.RecordedAt,
		arg.Source,
		arg.AccuracyM,
		arg.BookingID,
	)
	return err
}

const withdrawConsent = `-- name: WithdrawConsent :execrows
UPDATE tracking_consents SET withdrawn_at = now() WHERE booking_id = $1 AND user_id = $2 AND withdrawn_at IS NULL
`

type WithdrawConsentParams struct {
	BookingID uuid.UUID `json:"booking_id"`
	UserID    uuid.UUID `json:"user_id"`
}

func (q *Queries) WithdrawConsent(ctx context.Context, arg WithdrawConsentParams) (int64, error) {
	result, err := q.db.Exec(ctx, withdrawConsent, arg.BookingID, arg.UserID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
